#!/usr/bin/env python3
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# Parallel lanes each register the next VS IDs they see, so two changes can claim the same ones, and each
# appends its rows at the end of model/ids.toml and of a suite. So each VS ID a change adds that main already
# has becomes the next free one throughout the change, and a file the change only appends to is appended to on
# main instead of patched, so a change made against an older main still applies. propose-command and refresh
# both take this path.
#   prepare PATCH APPENDS  renumbers PATCH in place and moves its pure appends into APPENDS
#   append APPENDS         appends them, after the rest of the patch is applied
import re, json, sys
nl = chr(10)

def prepare(name, appends_name):
    text = open(name).read()
    parts = re.split('(?m)^(?=diff --git )', text)
    head, files = parts[0], parts[1:]
    have = set(int(n) for n in re.findall('(?m)^id = .VS-([0-9]+).', open('model/ids.toml').read()))
    added = []
    for f in files:
        added += [int(n) for n in re.findall('(?m)^[+]id = .VS-([0-9]+).', f)]
    top = max(have | set(added) | {0})
    ren = {}
    for n in added:
        if n in have and n not in ren:
            top += 1
            ren[n] = top
    def fix(line):
        return re.sub('VS-([0-9]+)(?![0-9])', lambda m: 'VS-' + str(ren[int(m.group(1))]).zfill(2) if int(m.group(1)) in ren else m.group(0), line)
    appends = {}
    kept = []
    for f in files:
        lines = [fix(l) if l.startswith('+') and not l.startswith('+++') else l for l in f.split(nl)]
        hunks = [i for i, l in enumerate(lines) if l.startswith('@@')]
        # The last hunk is a pure append when it removes nothing and ends on an added line, so no
        # context follows it: it reaches the end of the file. Any hunks before it are patched as usual.
        body = [l for l in lines[hunks[-1] + 1:] if l != ''] if hunks else []
        plain = 'new file mode' not in f and 'GIT binary patch' not in f
        if plain and body and body[-1].startswith('+') and not any(l[:1] in '-' + chr(92) for l in body):
            appends[lines[0].split(' ')[2][2:]] = [l[1:] for l in body if l.startswith('+')]
            if len(hunks) > 1:
                kept.append(nl.join(lines[:hunks[-1]]) + nl)
        else:
            kept.append(nl.join(lines))
    open(name, 'w').write(head + ''.join(kept))
    json.dump(appends, open(appends_name, 'w'))
    for n in sorted(ren):
        print('::notice::VS-' + str(n).zfill(2) + ' is already on main, so this change registers it as VS-' + str(ren[n]).zfill(2))

def append(appends_name):
    for path, add in json.load(open(appends_name)).items():
        old = open(path).read()
        if old and not old.endswith(nl):
            old += nl
        open(path, 'w').write(old + nl.join(add) + nl)

if sys.argv[1] == 'prepare':
    prepare(sys.argv[2], sys.argv[3])
else:
    append(sys.argv[2])
